/*
 * DEDICATED PUSH SERVICE WORKER
 * ═══════════════════════════════════════════════════════════════════════
 *
 * Dan, 2026-08-25: turning notifications on shows "Working..." for 10-15
 * seconds and then "Service worker startup timed out after 30s".
 *
 * WHY THE APP'S SERVICE WORKER COULD NOT BE USED FOR THIS
 *
 * /sw.js is generated by next-pwa and its install step runs
 * precacheAndRoute over 818 URLs. A service worker does not become
 * `activated` until install RESOLVES, which means all 818 downloads must
 * finish first. On a phone with one bar that is far longer than any
 * reasonable timeout — and if a SINGLE one of those 818 requests 404s or
 * times out, install REJECTS, the worker goes redundant, and it never
 * activates at all.
 *
 * Enrolling in push therefore sat waiting on the app's entire cache layer,
 * which is unrelated to push in every way except that both happen to be
 * service workers. Raising the timeout from 10s to 30s did not fix it and
 * could not: the worker was not slow, it was failing.
 *
 * This worker does push and nothing else. No precache, no fetch handler,
 * no routes. It installs in milliseconds and has nothing that can fail.
 *
 * SCOPE: registered at /push/ deliberately. Two registrations cannot share
 * a scope, and taking / would REPLACE the app's caching worker. A push
 * subscription works from any scope, and notifications shown from here can
 * still open any URL on the origin.
 */

const SP_PUSH_SW = 'sp-push-dedicated-v1';

self.addEventListener('install', () => {
    // Nothing to cache. Take over immediately rather than waiting for every
    // client to close — the whole point is that enrolling works right now.
    self.skipWaiting();
});

self.addEventListener('activate', (event) => {
    event.waitUntil(self.clients.claim());
});

self.addEventListener('message', (event) => {
    if (event?.data?.type === 'SP_SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('push', (event) => {
    let data = {};
    try {
        data = event.data ? event.data.json() : {};
    } catch (e) {
        // Some providers send plain text on a test send.
        try {
            data = { title: 'Smarter Poker', body: event.data ? event.data.text() : '' };
        } catch (e2) {
            data = { title: 'Smarter Poker', body: '' };
        }
    }

    const title = data.title || 'Smarter Poker';
    const url = data.url || '/hub';

    const options = {
        body: data.body || '',
        icon: data.icon || '/icons/icon-192.png',
        badge: data.badge || '/icons/icon-192.png',
        image: data.image || undefined,
        // notificationclick reads this back to decide where to go.
        data: { url, event: data.event || null, outboxId: data.outboxId || null },
        vibrate: data.vibrate || [120, 60, 120],
        requireInteraction: data.requireInteraction === true,
        // CHROME TRAP: showNotification throws and displays NOTHING when
        // renotify is true without a tag. Never set renotify unconditionally.
        tag: data.tag || undefined,
        renotify: data.tag ? true : undefined,
        actions: Array.isArray(data.actions) ? data.actions.slice(0, 2) : undefined,
        timestamp: data.sentAt || Date.now(),
    };

    event.waitUntil(
        self.registration
            .showNotification(title, options)
            // A rejected showNotification means the OS refused these options.
            // Retry with the bare minimum rather than showing nothing at all.
            .catch(() => self.registration.showNotification(title, { body: options.body }))
            .then(() => {
                try {
                    if (self.navigator && self.navigator.setAppBadge) {
                        if (typeof data.badgeCount === 'number') {
                            self.navigator.setAppBadge(data.badgeCount).catch(() => {});
                        } else {
                            self.navigator.setAppBadge().catch(() => {});
                        }
                    }
                } catch (e) { /* badging is a nicety */ }

                // Tell any open tab so the bell refreshes without a poll.
                return self.clients
                    .matchAll({ type: 'window', includeUncontrolled: true })
                    .then((clients) => {
                        for (const c of clients) {
                            try {
                                c.postMessage({ type: 'SP_PUSH_RECEIVED', event: data.event || null, url });
                            } catch (e) { /* one bad client must not stop the rest */ }
                        }
                    })
                    .catch(() => {});
            })
            .catch(() => {})
    );
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    try {
        if (self.navigator && self.navigator.clearAppBadge) {
            self.navigator.clearAppBadge().catch(() => {});
        }
    } catch (e) { /* ignore */ }

    if (event.action === 'decline') return;

    const url = (event.notification.data && event.notification.data.url) || '/hub';

    const samePath = (a, b) => {
        try {
            const x = new URL(a, self.location.origin);
            const y = new URL(b, self.location.origin);
            return x.pathname.replace(/\/+$/, '') === y.pathname.replace(/\/+$/, '');
        } catch (e) {
            return false;
        }
    };

    event.waitUntil(
        self.clients
            .matchAll({ type: 'window', includeUncontrolled: true })
            .then((clients) => {
                for (const c of clients) {
                    if ('focus' in c) {
                        c.focus();
                        if ('navigate' in c && url && !samePath(c.url, url)) {
                            try { c.navigate(url); } catch (e) { /* ignore */ }
                        }
                        return null;
                    }
                }
                return self.clients.openWindow ? self.clients.openWindow(url) : null;
            })
            .catch(() => null)
    );
});

/*
 * The browser can rotate a subscription without telling the page. Re-register
 * from here so the server learns the new endpoint even if the app is closed.
 */
self.addEventListener('pushsubscriptionchange', (event) => {
    event.waitUntil(
        (async () => {
            try {
                const res = await fetch('/api/push/vapid-public-key', { credentials: 'same-origin' });
                if (!res.ok) return;
                const { key } = await res.json();
                if (!key) return;

                const padding = '='.repeat((4 - (key.length % 4)) % 4);
                const base64 = (key + padding).replace(/-/g, '+').replace(/_/g, '/');
                const raw = self.atob(base64);
                const appKey = new Uint8Array(raw.length);
                for (let i = 0; i < raw.length; i += 1) appKey[i] = raw.charCodeAt(i);

                const sub = await self.registration.pushManager.subscribe({
                    userVisibleOnly: true,
                    applicationServerKey: appKey,
                });
                const json = sub.toJSON();

                let oldKeys = null;
                try {
                    if (event.oldSubscription && typeof event.oldSubscription.toJSON === 'function') {
                        oldKeys = event.oldSubscription.toJSON().keys || null;
                    }
                } catch (e) { /* ignore */ }

                await fetch('/api/push/rotate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        oldEndpoint: (event.oldSubscription && event.oldSubscription.endpoint) || null,
                        endpoint: sub.endpoint,
                        keys: json.keys,
                        oldKeys,
                    }),
                });
                console.log(`[${SP_PUSH_SW}] subscription self-healed`);
            } catch (err) {
                console.warn(`[${SP_PUSH_SW}] self-heal failed:`, err && err.message);
            }
        })()
    );
});
